D:  Axis-Parallel Rectangle

  ·ͣɺ࠷খͷ໘ੵͱͳΔΑ͏ͳ௕ํܗͷީิʹ͍ͭͯߟ͑ͯΈ·͢ɻ͜͜Ͱɺਤ1 ͷΑ͏ʹద౰ʹ K ఺Ҏ্ؚ
 ΜͰ͍ΔΑ͏ͳ௕ํ ܗ Λ ߟ ͑·͢ɻ͜ͷͱ͖ɺਤ2 ͷΑ͏ʹ ֤ ลΛ఺ʹ઀͢Δ·Ͱ௕ํ ܗ Λখͯ͘͞͠΋ɺؚ ·
 ΕΔ఺ͷ਺͸มΘΓ·ͤΜɻ





         ਤ1: 6 ͭͷ఺ΛؚΉ௕ํܗͷྫ          ਤ2: ಺෦ʹؚΉ఺ͷ਺Λม͑ͣʹ௕ํܗΛॖখ


  ͕ͨͬͯ͠ɺແݶʹ͋Δ௕ํܗͷީิ͔Βɺ༩͑ΒΕͨ఺ू߹ͷ࠲ඪΛ΋ͱʹͨ͠༗ݶͷީิʹߜΓࠐΊ·͢ɻ
 ۩ମతʹ͸ɺ௕ํܗ ͷࠨ ลͱӈล͸఺ू߹ͷ x ࠲ඪɺ௕ํܗͷ্ลͱԼล͸఺ू߹ͷ y ࠲ඪ͕ީิͱͳΓ·͢ɻ
  ͦ͏͢Δͱɺ௕ํ ܗ ͷ ީ ิΛશ୳ ࡧ Λ͢Δ͜ͱ͕ՄೳͱͳΓ·͢ɻ఺ू ߹ ͷ x ࠲ ඪ͔Β ࠨ ลͱӈลΛશ୳ ࡧ ͠
 ͯɺ఺ू ߹ ͷ y ࠲ ඪ͔Β௕ํ ܗ ͷ্ลͱԼลΛશ୳ ࡧ ͠·͢ɻ͜͜Ͱ௕ํ ܗ ͷ ܗ ͕ ܾ ·ΔͷͰɺ͋ͱ͸௕ํ ܗ ͷ
 ಺෦ʹؚ·ΕΔ఺ͷ਺Λ਺্͑͛ͯɺK ఺Ҏ্ͳΒ౴͑ͷީิͰ͢ɻ
  ͜ͷղ๏ͷ࣌ؒܭࢉྔ͸ O(N 5) ͱͳΓɺे෼ؒʹ߹͍·͢ɻ·ͨɺ௕ํܗͷ಺෦ʹؚ·ΕΔ఺ͷ਺ͷ਺্͑͛
 ʹ 2 ࣍ݩྦྷੵ࿨Λར༻͢Δͱɺ࣌ؒܭࢉྔΛ O(N 4) ʹվળ͢Δ͜ͱ͕ՄೳͰ͢ɻ


  C++ͷίʔυྫʢ࣌ؒܭࢉྔ͸ O(N 5)ʣ



 1 using ll = long long;


 2

 3 int main(void){

 4     int n,k;
 5     cin >> n >> k;


 6

 7     vector<int> x(n),y(n);

 8     vector<int> xary,yary;


 9

10     for(int i = 0; i < n; ++i){
11         cin >> x[i] >> y[i];



                                                  5

12         xary.push_back(x[i]);
13         yary.push_back(y[i]);

14     }


15

16     sort(begin(xary),end(xary));

17     sort(begin(yary),end(yary));


18

19     ll ans = 1LL * (xary[n-1] - xary[0]) * (yary[n-1] - yary[0]);


20

21     for(int xi = 0; xi < n; ++xi){

22         for(int xj = xi + 1; xj < n;++xj){

23             for(int yi = 0; yi < n; ++yi){

24                 for(int yj = yi + 1; yj < n;++yj){


25

26                     int num = 0;

27                     ll lx = xary[xi],rx = xary[xj];

28                     ll by = yary[yi],uy = yary[yj];


29

30                     for(int i = 0; i < n;++i){

31                         if(lx <= x[i] and x[i] <= rx and by <= y[i] and y[i] <= uy){

32                             num++;

33                         }

34                     }


35

36                     if(num >= k) ans = min(ans,1LL * (rx - lx) * (uy - by));

37                 }
38             }

39         }

40     }


41

42     cout << ans << endl;


43

44     return 0;

45 }





